package palindrome

import (
	"errors"
	"fmt"
)

// Product holds a palindrome and the pairs of factors within the range
// whose product equals it.
type Product struct {
	Value         int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromic products of two
// numbers within the inclusive range [fmin, fmax], along with all factor
// pairs that produce each.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	var min, max Product
	found := false

	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			product := i * j
			if !isPalindrome(product) {
				continue
			}
			if !found || product < min.Value {
				min = Product{product, [][2]int{{i, j}}}
				found = true
			} else if product == min.Value {
				min.Factorizations = append(min.Factorizations, [2]int{i, j})
			}
			if !found || product > max.Value {
				max = Product{product, [][2]int{{i, j}}}
			} else if product == max.Value {
				max.Factorizations = append(max.Factorizations, [2]int{i, j})
			}
		}
	}

	if !found {
		return Product{}, Product{}, errors.New("no palindromes")
	}

	return min, max, nil
}

// isPalindrome reports whether n reads the same forwards and backwards.
func isPalindrome(n int) bool {
	if n < 0 {
		return false
	}
	digits := 0
	for n > 0 {
		digits++
		n /= 10
	}
	for n > 0 {
		digits--
		n /= 10
	}
	return digits == 0
}

var _ = fmt.Sprintf // keep fmt import if unused in future edits

